parameters.jsCode:
const jobs = $input.all();

return [{
  json: {
    jobs: jobs.map((item, index) => ({
      number: index + 1,
      title: item.json.title,
      company: item.json.company,
      location: item.json.location,
      postedDate: item.json.postedDate,
      url: item.json.url
    }))
  }
}];

const now = new Date();
const days = 7;

return $input.all().filter(item => {
  const posted = new Date(item.json.postedDate);
  const diff = (now - posted) / (1000 * 60 * 60 * 24);

  return diff >= 0 && diff <= days;
});

const jobs = $json.jobs;

let html = `
<h2>🤖 AI Job Hunter - Today's Jobs</h2>
<p>Here are the latest LinkedIn jobs matching your profile:</p>
`;

for (const job of jobs) {
  html += `
    <div style="margin-bottom:20px;">
      <h3>${job.number}. ${job.title}</h3>
      <p>
        <b>Company:</b> ${job.company}<br>
        <b>Location:</b> ${job.location}<br>
        <b>Posted:</b> ${job.postedDate}
      </p>
      <a href="${job.url}">🔗 Apply on LinkedIn</a>
    </div>
    <hr>
  `;
}

return [{
  json: {
    subject: `🤖 AI Job Hunter - ${jobs.length} New Jobs`,
    html
  }
}];
